    return;
  }
  
  state.isScanning = true;
  console.log('[H3 Aspis] Starting page scan...');
  
  const addresses = findAddressesInDOM();
  
  if (addresses.length > 0) {
    console.log(`[H3 Aspis] Found ${addresses.length} unique addresses`);
    
