/**
 * Show scan complete notification badge
 * @param {number} count - Number of addresses scanned
 */
function showScanCompleteBadge(count) {
  // Remove existing badge
  const existing = document.getElementById('h3-aspis-scan-badge');
  if (existing) existing.remove();
  
  // Create badge
  const badge = document.createElement('div');
  badge.id = 'h3-aspis-scan-badge';
  badge.className = 'h3-aspis-scan-badge';
  badge.innerHTML = `
    <div class="h3-aspis-scan-badge-icon" style="background: linear-gradient(135deg, #e6e6fa, #d8bfd8);">🛡️</div>
    <div class="h3-aspis-scan-badge-text">
      H3 Aspis scanned ${count} address${count !== 1 ? 'es' : ''}
    </div>
    <span class="h3-aspis-scan-badge-close">×</span>
  `;
  
  // Add close handler
  badge.querySelector('.h3-aspis-scan-badge-close').addEventListener('click', (e) => {
    e.stopPropagation();
    badge.remove();
  });
  
  // Add click handler to open popup
  badge.addEventListener('click', () => {
    chrome.runtime.sendMessage({ type: 'OPEN_POPUP' });
    badge.remove();
  });
  
  document.body.appendChild(badge);
  
  // Auto-remove after 5 seconds
  setTimeout(() => {
    if (badge.parentElement) {
      badge.style.animation = 'slideInUp 0.3s ease reverse';
      setTimeout(() => badge.remove(), 300);
    }
  }, 5000);
}

/**
 * Observe DOM changes for dynamic content
 */
function observeDOMChanges() {
  state.mutationObserver = new MutationObserver((mutations) => {
    // Debounce rapid changes
    clearTimeout(state.debounceTimer);
    state.debounceTimer = setTimeout(() => {
      const hasNewContent = mutations.some(mutation => 
        mutation.addedNodes.length > 0 || 
        mutation.type === 'characterData'
      );
      
      if (hasNewContent) {
        console.log('[H3 Aspis] DOM changed, re-scanning...');
        scanPage();
      }
    }, SCAN_CONFIG.MUTATION_DEBOUNCE);
  });
  
  state.mutationObserver.observe(document.body, {
    childList: true,
    subtree: true,
    characterData: true
  });
}

/**
 * Get current page data for popup display
 * @returns {Array} Array of address data objects
 */
function getPageData() {
  const addresses = [];
  
  // Get all scanned addresses with results
  state.scannedAddresses.forEach(address => {
    // Safety check - address must exist and be a string
    if (!address || typeof address !== 'string') {
      console.warn('[H3 Aspis] Invalid address in scannedAddresses:', address);
      return;
    }
    
    const addressData = state.pendingAnalysis.get(address);
    const addressLower = address.toLowerCase();
    
    if (addressData && addressData.result) {
      // Has result
      addresses.push({
        address: address,
        status: addressData.result.status,
        summary: addressData.result.summary,
        riskLevel: addressData.result.riskLevel,
        flags: addressData.result.flags || [],
        tag: addressData.tag || (state.addressbook.has(addressLower) ? state.addressbook.get(addressLower).tag : null),
        isAddressbook: addressData.result.isAddressbook || false
      });
    } else if (addressData) {
      // Still analyzing
      addresses.push({
        address: address,
        status: 'analyzing',
        summary: addressData.tag ? `📋 ${addressData.tag} | Analyzing...` : 'Analysis in progress...',
        riskLevel: 'unknown',
        flags: [],
        tag: addressData.tag || null,
        isAddressbook: !!addressData.tag
      });
    } else {
      // No data yet (shouldn't happen, but handle it)
      addresses.push({
        address: address,
        status: 'pending',
        summary: 'Pending analysis...',
        riskLevel: 'unknown',
        flags: [],
        tag: state.addressbook.has(addressLower) ? state.addressbook.get(addressLower).tag : null
      });
    }
  });
  
  console.log('[H3 Aspis] Returning page data:', addresses.length, 'addresses');
  console.log('[H3 Aspis] Sample:', addresses.slice(0, 3));
  return addresses;
}

/**
 * Handle messages from background script
 * @param {Object} message - Message object
 * @param {Object} sender - Sender information
 * @param {Function} sendResponse - Response callback
 */
function handleMessage(message, sender, sendResponse) {
  console.log('[H3 Aspis] Received message:', message.type);
  
  switch (message.type) {
    case 'SCAN_RESULTS':
      highlightAddresses(message.results);
      sendResponse({ success: true });
      break;
      
    case 'SINGLE_RESULT':
      // Handle result for a single address
      if (message.address && message.result) {
        const addressLower = message.address.toLowerCase();
        
        // Get existing data (which may have tag info)
        const addressData = state.pendingAnalysis.get(addressLower) || { nodes: [] };
        
        // Merge result with tag if exists
        const finalResult = { ...message.result };
        if (addressData.tag) {
          finalResult.tag = addressData.tag;
          finalResult.isAddressbook = true;
          // Prepend tag to summary
          finalResult.summary = `📋 ${addressData.tag} | ${message.result.summary}`;
        }
        
        // Store complete result
        addressData.result = finalResult;
        state.pendingAnalysis.set(addressLower, addressData);
        
        // Mark as scanned (in case it wasn't already)
        state.scannedAddresses.add(addressLower);
        
        // Highlight the address with final result
        highlightAddress(message.address, finalResult);
      }
      sendResponse({ success: true });
      break;
      
    case 'GET_PAGE_DATA':
      // Return current page data for popup
      const pageData = getPageData();
      sendResponse({ success: true, addresses: pageData });
      break;
      
    case 'RESCAN_PAGE':
      state.scannedAddresses.clear();
      state.pendingAnalysis.clear();
      scanPage();
      sendResponse({ success: true });
      break;
      
    case 'CLEAR_HIGHLIGHTS':
      clearAllHighlights();
      sendResponse({ success: true });
      break;
      
    case 'RELOAD_ADDRESSBOOK':
      console.log('[H3 Aspis] Reloading addressbook and rescanning page...');
      loadAddressbook().then(() => {
        // Clear existing highlights before rescanning
        clearAllHighlights();
        state.scannedAddresses.clear();
        state.pendingAnalysis.clear();
        
        // Rescan with updated addressbook
        scanPage();
        sendResponse({ success: true });
      });
      return true; // Async response
      
    default:
      console.warn('[H3 Aspis] Unknown message type:', message.type);
      sendResponse({ success: false, error: 'Unknown message type' });
  }
  
  return true; // Keep channel open for async response
}

/**
 * Clear all highlights from the page
 */
function clearAllHighlights() {
  const highlights = document.querySelectorAll('.h3-aspis-highlight');
  highlights.forEach(span => {
    const text = span.textContent;
    const textNode = document.createTextNode(text);
    span.parentElement?.replaceChild(textNode, span);
  });
  
  state.scannedAddresses.clear();
  console.log('[H3 Aspis] Highlights cleared');
}

